import java.io.*;
import java.util.*;

public class J implements Runnable {

    private static final boolean ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null;

    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer = new StringTokenizer("");

    private void setup() throws FileNotFoundException {
        Locale.setDefault(Locale.US);
        String filename = "";
        if (ONLINE_JUDGE && filename.isEmpty()) {
            reader = new BufferedReader(new InputStreamReader(System.in));
            writer = new PrintWriter(System.out);
        } else {
            if (filename.isEmpty()) {
                reader = new BufferedReader(new FileReader("input.txt"));
                writer = new PrintWriter(new FileWriter("output.txt"));
            } else {
                reader = new BufferedReader(new FileReader(filename + ".in"));
                writer = new PrintWriter(new FileWriter(filename + ".out"));
            }
        }
    }

    String getNextToken() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    int getNextInt() throws IOException {
        return Integer.parseInt(getNextToken());
    }

    long getNextLong() throws IOException {
        return Long.parseLong(getNextToken());
    }

    double getNextDouble() throws IOException {
        return Double.parseDouble(getNextToken());
    }

    int[] readArray(int size) throws IOException {
        int[] array = new int[size];
        for (int i = 0; i < size; i++) {
            array[i] = getNextInt();
        }
        return array;
    }

    public static void main(String[] args) {
        new J().run();
    }

    long startTime, endTime;

    void measureTime() {
        endTime = System.currentTimeMillis();
        System.err.println("Elapsed time: " + (endTime - startTime));
    }

    @Override
    public void run() {
        try {
            startTime = System.currentTimeMillis();
            setup();
            process();
            writer.close();
            measureTime();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(-1);
        }
    }

    int[][][][] dpTable;
    char[] sequence;
    int INF = 10000000;

    int countChars(char[] arr, char target, int v, int k, int x) {
        int cost = 0;
        for (char c : arr) {
            if (c == 'V') {
                v--;
                if (v == 0 && target == 'V') return cost;
                if (v < 0) cost++;
            }
            if (c == 'K') {
                k--;
                if (k == 0 && target == 'K') return cost;
                if (k < 0) cost++;
            }
            if (c == 'X') {
                x--;
                if (x == 0 && target == 'X') return cost;
                if (x < 0) cost++;
            }
        }
        throw new RuntimeException();
    }

    private void process() throws IOException {
        int n = getNextInt();
        sequence = getNextToken().toCharArray();
        int vCount = 0, kCount = 0, xCount = 0;
        for (int i = 0; i < sequence.length; i++) {
            if (sequence[i] == 'V') vCount++;
            else if (sequence[i] == 'K') kCount++;
            else {
                sequence[i] = 'X';
                xCount++;
            }
        }
        dpTable = new int[vCount + 1][kCount + 1][xCount + 1][3];
        for (int[][][] arr3d : dpTable) {
            for (int[][] arr2d : arr3d) {
                for (int[] arr1d : arr2d) {
                    Arrays.fill(arr1d, INF);
                }
            }
        }
        for (int i = 0; i < 3; i++) {
            dpTable[0][0][0][i] = 0;
        }
        for (int v = 0; v <= vCount; v++) {
            for (int k = 0; k <= kCount; k++) {
                for (int x = 0; x <= xCount; x++) {
                    for (int prevState = 0; prevState < 3; prevState++) {
                        int currentCost = dpTable[v][k][x][prevState];
                        if (currentCost == INF) continue;
                        if (v + 1 <= vCount) {
                            int costV = countChars(sequence, 'V', v + 1, k, x);
                            dpTable[v + 1][k][x][0] = Math.min(dpTable[v + 1][k][x][0], currentCost + costV);
                        }
                        if (k + 1 <= kCount) {
                            int costK = countChars(sequence, 'K', v, k + 1, x);
                            if (prevState != 0) {
                                dpTable[v][k + 1][x][1] = Math.min(dpTable[v][k + 1][x][1], currentCost + costK);
                            }
                        }
                        if (x + 1 <= xCount) {
                            int costX = countChars(sequence, 'X', v, k, x + 1);
                            dpTable[v][k][x + 1][2] = Math.min(dpTable[v][k][x + 1][2], currentCost + costX);
                        }
                    }
                }
            }
        }
        int answer = INF;
        for (int i = 0; i < 3; i++) {
            answer = Math.min(answer, dpTable[vCount][kCount][xCount][i]);
        }
        writer.println(answer);
    }
}
