import sys
import math

def main():
    INF = 10000000

    def count_chars(arr, target, v, k, x):
        cost = 0
        for c in arr:
            if c == 'V':
                v -= 1
                if v == 0 and target == 'V':
                    return cost
                if v < 0:
                    cost += 1
            elif c == 'K':
                k -= 1
                if k == 0 and target == 'K':
                    return cost
                if k < 0:
                    cost += 1
            elif c == 'X':
                x -= 1
                if x == 0 and target == 'X':
                    return cost
                if x < 0:
                    cost += 1
        raise RuntimeError()

    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    sequence_str = list(input_data[1])
    sequence = sequence_str.copy()

    vCount = 0
    kCount = 0
    xCount = 0

    for i in range(len(sequence)):
        if sequence[i] == 'V':
            vCount += 1
        elif sequence[i] == 'K':
            kCount += 1
        else:
            sequence[i] = 'X'
            xCount += 1

    # Initialize DP table
    dp = [[[[INF for _ in range(3)] for _ in range(xCount + 1)] for _ in range(kCount + 1)] for _ in range(vCount + 1)]
    for i in range(3):
        dp[0][0][0][i] = 0

    for v in range(vCount + 1):
        for k in range(kCount + 1):
            for x in range(xCount + 1):
                for prev_state in range(3):
                    current_cost = dp[v][k][x][prev_state]
                    if current_cost == INF:
                        continue
                    # Add 'V'
                    if v + 1 <= vCount:
                        cost_v = count_chars(sequence, 'V', v + 1, k, x)
                        if dp[v + 1][k][x][0] > current_cost + cost_v:
                            dp[v + 1][k][x][0] = current_cost + cost_v
                    # Add 'K'
                    if k + 1 <= kCount:
                        cost_k = count_chars(sequence, 'K', v, k + 1, x)
                        if prev_state != 0:
                            if dp[v][k + 1][x][1] > current_cost + cost_k:
                                dp[v][k + 1][x][1] = current_cost + cost_k
                    # Add 'X'
                    if x + 1 <= xCount:
                        cost_x = count_chars(sequence, 'X', v, k, x + 1)
                        if dp[v][k][x + 1][2] > current_cost + cost_x:
                            dp[v][k][x + 1][2] = current_cost + cost_x

    answer = min(dp[vCount][kCount][xCount])
    print(answer)

if __name__ == "__main__":
    main()

